#!/bin/bash
# Renders the kit models listed in kits.txt (name|file in assets|height m|length m|[smooth]|[#body colour for name-coloured OBJ parts]|[flip: turn it to face the camera]) with K_show: one still each and a labelled sheet.
# Usage: bash make-kits.sh [kits.txt] [out-folder]   (default 3-free-kits; varieties: bash make-kits.sh kits-variety.txt 4-free-kit-varieties)      (no pipeline run, no AI model)
set -e
HERE="$(cd "$(dirname "$0")" && pwd)"; ROOT="$(cd "$HERE/../../.." && pwd)"; LIST="$HERE/${1:-kits.txt}"; OUT="$HERE/${2:-3-free-kits}"; mkdir -p "$OUT"
python3 - "$HERE" "$LIST" <<'PY'
import json, sys
here, lst = sys.argv[1], sys.argv[2]
rows = [l.strip().split("|") for l in open(lst) if l.strip() and not l.startswith("#")]
sc = [{"image": "", "start": i, "duration": 1, "motion": "zoom-in", "engine": "custom", "component": "K_show",
       "props": {"file": f, "h": float(h), "l": float(l), "smooth": "smooth" in r[4:], "flip": "flip" in r[4:], **({"body": [x for x in r[4:] if x.startswith("#")][0]} if any(x.startswith("#") for x in r[4:]) else {})}} for i, r in enumerate(rows) for (n, f, h, l) in [r[:4]]]
json.dump({"width": 1920, "height": 1080, "fps": 30, "title": "Kit objects", "accent": "#FFB703", "scenes": sc, "voice": "", "music": None, "captions": [], "durationSec": len(sc)},
          open(f"{here}/project/timeline-kits.json", "w"), indent=1)
open(f"{here}/project/kits-names.txt", "w").write(" ".join(r[0] for r in rows))
PY
NAMES=$(cat "$HERE/project/kits-names.txt"); N=$(echo $NAMES | wc -w | tr -d ' ')
SRC="$ROOT/templates/remotion/src/custom"; find "$SRC" -mindepth 1 ! -name index.ts -delete
{ echo "// Generated by make-kits.sh. Do not edit by hand."; names=()
  for f in "$HERE"/project/custom/*.tsx; do n="$(basename "$f" .tsx)"; cp "$f" "$SRC/$n.tsx"; case "$n" in _*) continue;; esac; names+=("$n"); echo "import $n from \"./$n\";"; done
  echo "export const custom: Record<string, React.FC<any>> = { $(IFS=,; echo "${names[*]}" | sed 's/,/, /g') };"; } > "$SRC/index.ts"
cd "$ROOT/templates/remotion"; i=0
for a in $NAMES; do npx remotion still src/index.ts Main "$OUT/$a.png" --props="$HERE/project/timeline-kits.json" --public-dir="$HERE/assets" --frame=$((i*30+20)) --gl=angle --log=error; i=$((i+1)); done
cd "$OUT"; args=(); f=""; k=0
for a in $NAMES; do args+=(-i "$a.png"); f="$f[$k]scale=480:-1,drawtext=text='$a':x=12:y=10:fontsize=28:fontcolor=black:box=1:boxcolor=white@0.7:boxborderw=6[c$k];"; k=$((k+1)); done
cols=6; rows=$(( (N + cols - 1) / cols )); pad=$(( cols * rows - N ))
while [ "$pad" -gt 0 ]; do args+=(-f lavfi -i "color=c=white:s=480x270"); f="$f[$k]null[c$k];"; k=$((k+1)); pad=$((pad-1)); done   # (BSD seq 1 0 counts down, so no seq here)
ffmpeg -v error -y "${args[@]}" -filter_complex "${f}$(for j in $(seq 0 $((k-1))); do printf "[c$j]"; done)xstack=inputs=$k:grid=${cols}x${rows}" -frames:v 1 -update 1 sheet.png
echo "$OUT/sheet.png"
# street scene with every kit object and a person for scale
python3 -c "import json; json.dump({'width':1920,'height':1080,'fps':30,'title':'Kit street','accent':'#FFB703','scenes':[{'image':'','start':0,'duration':1,'motion':'zoom-in','engine':'custom','component':'K_street'}],'voice':'','music':None,'captions':[],'durationSec':1}, open('$HERE/project/timeline-street.json','w'))"
cd "$ROOT/templates/remotion" && npx remotion still src/index.ts Main "$OUT/street.png" --props="$HERE/project/timeline-street.json" --public-dir="$HERE/assets" --frame=20 --gl=angle --log=error
echo "$OUT/street.png"
